package app.kinnect.live;
import android.app.*;import android.content.*;import android.os.*;import android.text.*;import android.view.*;import android.widget.*;import org.json.*;import java.util.*;
/** Admin-only targeted/broadcast trial coin grants with server snapshot and explicit confirmation. */
public final class CoinGrantActivity extends Activity {
 private CommerceUi ui;private EditText amount,search;private Switch everyone;private LinearLayout people;private TextView selected;private Button send;private final Set<String> ids=new LinkedHashSet<>();private int searchRevision;private boolean busy;private JSONObject prepared;
 protected void attachBaseContext(Context c){super.attachBaseContext(I18n.localized(c));}
 public void setContentView(View v){super.setContentView(CommerceChrome.wrap(this,v));}
 public void onCreate(Bundle b){super.onCreate(b);ui=new CommerceUi(this);NativeApi.shared.initialize(this,ServerConfig.DEFAULT_ORIGIN);getWindow().setStatusBarColor(ui.bg);getWindow().setNavigationBarColor(ui.bg);getWindow().getDecorView().setSystemUiVisibility(WebTheme.isDark(this)?0:View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR|View.SYSTEM_UI_FLAG_LIGHT_NAVIGATION_BAR);draw();loadPeople("");}
 private String number(long n){return java.text.NumberFormat.getIntegerInstance(new java.util.Locale("vi","VN")).format(n);}
 private void toast(String s){if(SuccessEffects.message(this,s))return;Toast.makeText(this,I18n.t(s),Toast.LENGTH_LONG).show();}
 private void count(){selected.setText(I18n.t(everyone.isChecked()?"Đã chọn · Tất cả":"Đã chọn")+(everyone.isChecked()?"":" · "+ids.size()));boolean enabled=!busy&&(everyone.isChecked()||!ids.isEmpty());send.setEnabled(enabled);send.setTextColor(enabled?android.graphics.Color.WHITE:ui.muted);for(android.graphics.drawable.Drawable icon:send.getCompoundDrawablesRelative())if(icon!=null)icon.setTint(enabled?android.graphics.Color.WHITE:ui.muted);send.setBackground(ui.round(enabled?ui.purple:ui.soft,14));}
 private void draw(){LinearLayout root=ui.col();root.setBackgroundColor(ui.bg);root.addView(ui.header("Tặng xu",ui.icon("history","Lịch sử tặng xu",this::history)));ScrollView scroll=new ScrollView(this);LinearLayout body=ui.col();body.setPadding(ui.dp(18),0,ui.dp(18),ui.dp(20));scroll.addView(body);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));LinearLayout card=ui.section();card.addView(ui.text("Xu mỗi người",14,ui.ink,true));amount=new KinnectInput(this);amount.setTag("grants:amount");amount.setInputType(2);amount.setSingleLine(true);amount.setText("2000");amount.setTextColor(ui.ink);amount.setHintTextColor(ui.muted);amount.setBackground(ui.round(ui.soft,12));amount.setPadding(ui.dp(12),ui.dp(12),ui.dp(12),ui.dp(12));amount.setTextSize(24);amount.setFilters(new InputFilter[]{new InputFilter.LengthFilter(7)});amount.setMinHeight(ui.dp(72));card.addView(amount,new LinearLayout.LayoutParams(-1,-2));ui.add(body,card,12);everyone=new Switch(this);everyone.setText(I18n.t("Tất cả thành viên"));everyone.setTextColor(ui.ink);everyone.setThumbTintList(android.content.res.ColorStateList.valueOf(WebTheme.isDark(this)?0xffc4b5fd:0xff6c47e0));everyone.setTrackTintList(android.content.res.ColorStateList.valueOf(WebTheme.isDark(this)?0xff574672:0xffd6c9f7));everyone.setTextSize(14);everyone.setMinHeight(ui.dp(48));everyone.setTag("grants:all");ui.add(body,everyone,10);selected=ui.text("Đã chọn · 0",13,ui.ink,true);selected.setTag("grants:count");ui.add(body,selected,8);search=new KinnectInput(this);search.setSingleLine(true);search.setHint(I18n.t("Tìm tên hoặc @tài khoản"));search.setTextColor(ui.ink);search.setHintTextColor(ui.muted);search.setBackground(ui.round(ui.soft,12));search.setPadding(ui.dp(12),ui.dp(12),ui.dp(12),ui.dp(12));search.setTextSize(14);search.setTag("grants:search");ui.add(body,search,10);people=ui.col();ui.add(body,people,8);everyone.setOnCheckedChangeListener((v,on)->{search.setEnabled(!on);people.setVisibility(on?View.GONE:View.VISIBLE);count();});search.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int a,int c,int f){}public void onTextChanged(CharSequence s,int a,int before,int count){final int rev=++searchRevision;search.postDelayed(()->{if(rev==searchRevision)loadPeople(search.getText().toString());},300);}public void afterTextChanged(Editable e){}});LinearLayout foot=ui.col();foot.setPadding(ui.dp(18),ui.dp(8),ui.dp(18),ui.dp(12));send=ui.action("Tiếp tục","gift",this::preview);send.setTag("grants:review");foot.addView(send,new LinearLayout.LayoutParams(-1,-2));root.addView(foot);setContentView(root);count();}
 private void loadPeople(String q){final int rev=searchRevision;try{NativeApi.shared.call("GET","/api/admin/coin-grants/people?q="+java.net.URLEncoder.encode(q,"UTF-8"),null,(data,error,status)->{if(isFinishing()||isDestroyed()||rev!=searchRevision)return;if(error!=null){people.removeAllViews();people.addView(ui.empty("shield_check",status==403?"Chỉ dành cho admin":"Chưa tải được thành viên"));return;}renderPeople(data.optJSONArray("people"));});}catch(Exception e){toast("Chưa tìm được thành viên.");}}
 private void renderPeople(JSONArray rows){people.removeAllViews();if(rows==null||rows.length()==0){people.addView(ui.empty("users_round","Không tìm thấy thành viên"));return;}for(int i=0;i<rows.length();i++){JSONObject person=rows.optJSONObject(i);if(person==null)continue;String id=person.optString("id");CheckBox check=new CheckBox(this);check.setTag("grants:user:"+id);check.setText(person.optString("name")+"\n@"+person.optString("username"));check.setTextSize(14);check.setTextColor(ui.ink);check.setButtonTintList(android.content.res.ColorStateList.valueOf(ui.purple));check.setMinHeight(ui.dp(64));check.setPadding(ui.dp(4),ui.dp(8),ui.dp(4),ui.dp(8));check.setChecked(ids.contains(id));check.setOnCheckedChangeListener((v,on)->{if(on){if(ids.size()>=500){check.setChecked(false);toast("Tối đa 500 người mỗi lượt chọn.");return;}ids.add(id);}else ids.remove(id);count();});people.addView(check,new LinearLayout.LayoutParams(-1,-2));}}
 private void preview(){if(busy)return;long coins;try{coins=Long.parseLong(amount.getText().toString().trim());if(coins<1||coins>1000000)throw new Exception();}catch(Exception e){toast("Nhập từ 1 đến 1.000.000 xu mỗi người.");return;}busy=true;count();try{JSONObject payload=new JSONObject().put("coins",coins).put("all",everyone.isChecked()).put("userIds",everyone.isChecked()?new JSONArray():new JSONArray(ids));NativeApi.shared.call("POST","/api/admin/coin-grants/preview",payload,(data,error,status)->{busy=false;if(isFinishing()||isDestroyed())return;count();if(error!=null){toast("Chưa chuẩn bị được lượt tặng. Hãy kiểm tra danh sách.");return;}prepared=data;confirmation();});}catch(Exception e){busy=false;count();toast("Chưa chuẩn bị được lượt tặng.");}}
 private void confirmation(){if(prepared==null)return;new Sheet(this).setTitle(I18n.t("Xác nhận tặng xu")).setMessage(number(prepared.optInt("count"))+" "+I18n.t("thành viên")+"\n"+number(prepared.optLong("coins"))+" "+I18n.t("xu mỗi người")+"\n\n"+I18n.t("Tổng xu")+" · "+number(prepared.optLong("totalCoins"))+"\n"+I18n.t("Xu trải nghiệm, không quy đổi thành tiền.")).setPositiveButton(I18n.t("Tặng xu"),(d,w)->commit()).setNegativeButton(I18n.t("Hủy"),null).show();}
 private void commit(){if(busy||prepared==null)return;busy=true;count();try{NativeApi.shared.call("POST","/api/admin/coin-grants/confirm",new JSONObject().put("id",prepared.optString("id")),(data,error,status)->{busy=false;if(isFinishing()||isDestroyed())return;count();if(error!=null){if(status==409||status==403){prepared=null;toast("Danh sách hoặc quyền đã thay đổi. Hãy chọn lại.");}else new Sheet(this).setTitle(I18n.t("Chưa xác nhận được kết quả")).setMessage(I18n.t("Thử lại cùng lượt tặng sẽ không cộng xu hai lần.")).setPositiveButton(I18n.t("Thử lại"),(d,w)->commit()).setNegativeButton(I18n.t("Đóng"),null).show();return;}prepared=null;toast("Đã tặng xu");});}catch(Exception e){busy=false;count();toast("Chưa xác nhận được kết quả.");}}
 private void history(){NativeApi.shared.call("GET","/api/admin/coin-grants",null,(data,error,status)->{if(isFinishing()||isDestroyed())return;if(error!=null){toast("Chưa tải được lịch sử.");return;}LinearLayout list=ui.col();JSONArray rows=data.optJSONArray("grants");int count=0;for(int i=0;rows!=null&&i<rows.length();i++){JSONObject item=rows.optJSONObject(i);if(item==null||!item.optString("state").equals("done"))continue;count++;TextView text=ui.text(number(item.optLong("coins"))+" "+I18n.t("xu")+" × "+item.optInt("count")+"\n"+new java.text.SimpleDateFormat("dd/MM/yyyy HH:mm",java.util.Locale.getDefault()).format(new java.util.Date(item.optLong("completed"))),14,ui.ink,false);text.setPadding(0,ui.dp(12),0,ui.dp(12));list.addView(text);}if(count==0)list.addView(ui.empty("history","Chưa có lượt tặng"));ScrollView scroll=new ScrollView(this);scroll.addView(list);scroll.setLayoutParams(new LinearLayout.LayoutParams(-1,getResources().getDisplayMetrics().heightPixels/2));new Sheet(this).setTitle(I18n.t("Lịch sử tặng xu")).setView(scroll).setPositiveButton(I18n.t("Đóng"),null).show();});}
}
